    select @stagedRecords = count(1) from [Staging].[EcoPortal_incident_investigations];

    -- Do not run if there are no records in source
    if( @stagedRecords = 0 )
    begin
        -- Select return parameters as a dataset
        select    0                as ErrorRecords,
                0                as InsertRecords,
                0                as UpdateRecords,
                0                as DeleteRecords,
                1                as Completed,
                null            as TargetRecords;
        return;
    end;


    -- Check if there are records in the target table
    set @targetRecords = (select count(1) from [Working].[EcoPortal_incident_investigations]);

    -- On first pass / initial load only insert from landing, as existing data folders (main/working) will be empty
    if ( (@pMode = 'initial') or (@targetRecords = 0) )
    begin

