            ) as
        select  src.[page_id] ,src.[page_uid] ,src.[page_name] ,src.[is_archived] ,src.[created_date_time] ,src.[created_time_zone] ,src.[updated_date_time] ,src.[updated_time_zone] ,src.[current_stage_id] ,src.[current_stage_name] ,src.[active_stage] ,src.[locations_raw_json] ,src.[tags_raw_json] ,src.[total_field_count] ,src.[field_type_count] ,src.[ai_acc_claim_ref_number_plaintext] ,src.[ai_acc_claim_attach_doc_select] ,src.[ai_abuse_null_checklist] ,src.[ai_actual_severity_consequence_guidance_select] ,src.[ai_actual_severity_guideline_plaintext] ,src.[ai_actual_severity_likelihood_guidance_select] ,src.[ai_actual_severity_likelihood_occurrence_select] ,src.[ai_actual_severity_gauge_gauge] ,src.[ai_actual_severity_gauge_number] ,src.[ai_actual_severity_level_select] ,src.[ai_actual_severity_consequence_select] ,src.[ai_assault_null_checklist] ,src.[ai_asset_damage_approx_cost_number] ,src.[ai_asset_damage_insurance_claim_select] ,src.[ai_asset_damage_type_select] ,src.[ai_email_evidence_emails_relevant_geo] ,src.[ai_exp_first_injured_job_duration_select] ,src.[ai_exp_first_injured_shift_duration_select] ,src.[ai_exp_first_injured_employee_plaintext] ,src.[ai_fire_risk_cooking_null_checklist] ,src.[ai_fire_risk_other_null_checklist] ,src.[ai_illness_injury_next_monitoring_date] ,src.[ai_illness_injury_category_select] ,src.[ai_illness_injury_monitoring_details_unknown] ,src.[ai_illness_injury_monitoring_required_select] ,src.[ai_illness_injury_treatment_select] ,src.[ai_illness_injury_type_select] ,src.[ai_illness_injury_cause_select] ,src.[ai_improvement_actions_list] ,src.[ai_root_cause_why_1_plaintext] ,src.[ai_root_cause_why_2_plaintext] ,src.[ai_root_cause_why_3_plaintext] ,src.[ai_root_cause_why_4_plaintext] ,src.[ai_root_cause_attach_docs_file] ,src.[ai_root_cause_attach_photos_imagegallery] ,src.[ai_root_cause_facts_findings_unknown] ,src.[ai_root_cause_is_root_cause_select] ,src.[ai_root_cause_timeline_unknown] ,src.[ai_injury_null_imagegallery] ,src.[ai_injury_body_parts_affected_select] ,src.[ai_investigation_attach_files_file] ,src.[ai_investigation_comments_unknown] ,src.[ai_investigation_final_date] ,src.[ai_investigation_completed_select] ,src.[ai_investigation_details_null_unknown] ,src.[ai_investigation_details_attach_files_file] ,src.[ai_investigation_details_comments_unknown] ,src.[ai_investigation_details_initial_date] ,src.[ai_investigation_details_external_individuals_unknown] ,src.[ai_investigation_details_team_members_people] ,src.[ai_notifiable_incident_status_select] ,src.[ai_notifiable_incident_details_null_unknown] ,src.[ai_notifiable_injury_illness_null_unknown] ,src.[ai_notifiable_injury_illness_is_notifiable_select] ,src.[ai_notification_null_unknown] ,src.[ai_ongoing_risk_consequence_guidance_select] ,src.[ai_ongoing_risk_likelihood_guidance_select] ,src.[ai_ongoing_risk_expected_outcome_select] ,src.[ai_ongoing_risk_gauge_gauge] ,src.[ai_ongoing_risk_gauge_number] ,src.[ai_ongoing_risk_level_select] ,src.[ai_ongoing_risk_reoccurrence_likelihood_select] ,src.[ai_ongoing_risk_control_actions_plaintext] ,src.[ai_risks_controls_null_unknown] ,src.[ai_risks_controls_hazards_contribute_select] ,src.[ai_smoking_null_checklist] ,src.[co_close_out_null_checklist] ,src.[co_close_out_comments_unknown] ,src.[co_close_out_date] ,src.[co_lifecycle_days_investigation_closeout_number] ,src.[co_lifecycle_days_investigation_closeout_unknown] ,src.[co_lifecycle_days_report_investigation_number] ,src.[co_lifecycle_days_report_investigation_unknown] ,src.[co_lifecycle_period_investigation_closeout_select] ,src.[co_lifecycle_period_report_closeout_select] ,src.[co_lifecycle_period_report_investigation_select] ,src.[co_lifecycle_severity_guideline_select] ,src.[co_lifecycle_total_active_period_number] ,src.[co_lifecycle_total_active_period_unknown] ,src.[rpt_null_null_unknown] ,src.[rpt_null_business_unit_select] ,src.[rpt_null_external_people_unknown] ,src.[rpt_null_external_witnesses_unknown] ,src.[rpt_null_eve